use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,path::Path,process::Command};
fn main(){let r=Path::new("/home/ubuntu/src/zopro-perf-work/g2-vector-sign-compat175");let d=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-30-g2-vector-sign-compat175");let read=|p:&Path|->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()};let hash=|b:&[u8]|format!("{:x}",Sha256::digest(b));let declared=read(&d.join("artifacts/review.json"));let mut archives=BTreeMap::new();
 for(name,key)in[("source","source_members"),("helpers","helper_members"),("receipts","receipt_members"),("proofs","proof_public_members")]{let p=d.join(format!("artifacts/{name}.json.gz"));let o=Command::new("gzip").args(["-d","-c"]).arg(&p).output().unwrap();assert!(o.status.success());let data:Value=serde_json::from_slice(&o.stdout).unwrap();let map=data.as_object().unwrap();assert_eq!(declared[key],map.len());let base=if name=="source"{r.join("source")}else{r.to_path_buf()};for(f,v)in map{assert!(!Path::new(f).is_absolute());assert!(!Path::new(f).components().any(|c|matches!(c,std::path::Component::ParentDir)));let b=v["bytes"].as_array().unwrap().iter().map(|x|u8::try_from(x.as_u64().unwrap()).unwrap()).collect::<Vec<_>>();assert_eq!(hash(&b),v["sha256"]);assert_eq!(b,fs::read(base.join(f)).unwrap());}archives.insert(name,json!({"members":map.len(),"member_hashes_and_bytes_match_originals":true,"sha256":hash(&fs::read(p).unwrap())}));}
 let a=read(&d.join("artifacts/analysis.json"));assert_eq!(a,read(&r.join("analysis.json")));assert_eq!(a["independent_proof_count"],26292);assert_eq!(a["new_independent_exports"],89);assert_eq!(a["SDK_requests"],248);
 let p=Path::new("/home/ubuntu/src/zopro-perf-work/g2-vector-sign-sdk175/source");let audit=read(&r.join("source-reuse.json"));assert_eq!(audit["source_files"],176);let manifest=read(Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-29-balanced-kh-adoption/artifacts/production-source-manifest.json"));for(name,h)in manifest["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(&fs::read(Path::new("/home/ubuntu/src/zk-tools/zopro").join(name)).unwrap()),h.as_str().unwrap());assert_eq!(fs::read(r.join("source").join(name)).unwrap(),fs::read(p.join(name)).unwrap());}
 assert_eq!(fs::read(d.join("accepted-rows.json")).unwrap(),fs::read("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-30-g2-vector-sign-sdk175/accepted-rows.json").unwrap());let review=read(&r.join("qualification-review.json"));assert_eq!(review["passed"],true);assert_eq!(review["owned_services_remaining"],0);assert!(review["owned_control_directories_remaining"].as_array().unwrap().is_empty());
 fs::copy(r.join("qualification-review.json"),d.join("artifacts/qualification-review.json")).unwrap();
 let md=fs::read_to_string(d.join("README.md")).unwrap();let mut tail=md.as_str();let mut links=0;while let Some(i)=tail.find("]("){tail=&tail[i+2..];let Some(j)=tail.find(')')else{break};let link=tail[..j].split('#').next().unwrap();if !link.is_empty()&&!link.starts_with("http"){assert!(d.join(link).exists(),"{link}");links+=1;}tail=&tail[j+1..];}
 fs::write(d.join("artifacts/post-publication-review.json"),serde_json::to_vec_pretty(&json!({"passed":true,"archives":archives,"independent_qualification_review_passed":true,"all175production_files_unchanged":true,"all_source_members_byte_exact_to_measured_candidate":true,"all9accepted_local_AWS_CPU_Metal_reference_rows_exact":true,"verified_ledger":26292,"new_exports":89,"SDK_requests":248,"owned_services_and_controls_clean":true,"readme_links_checked":links,"performance_or_native_test_or_verifier_reruns":0,"original_full_performance_gate":false,"adopted":false,"goal_achieved":false})).unwrap()).unwrap();println!("Archive/memberbytes/qualification/counts/175production/source/9rows/{links}links PASS; ledger26292, notadopted");
}
